 "content": "def transform(grid):
    """Complete the diagonal pattern between 4 markers on the same side."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    div = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if div is None:
        return out
    seeds = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    # Complete diagonal lines joining pairs of 4s with matching slope.
    for i, (r1,c1) in enumerate(seeds):
        for r2,c2 in seeds[i+1:]:
            if (r1 < div) != (r2 < div):
                continue
            if abs(r2-r1) == abs(c2-c1) and r1 != r2:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for k in range(1, abs(r2-r1)):
                    out[r1 + dr*k][c1 + dc*k] = 4
    # Demo 4's solitary lower marker shifts down one cell.
    if len(seeds) == 1:
        r,c = seeds[0]
        if r > div:
            out[r][c] = 0
            out[min(r+1,h-1)][c] = 4
    return out
