 "content": "def transform(grid):
    """Project each 4 one cell toward its nearest outer grid edge."""
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 2:
                out[r][c] = 2
            elif v == 4:
                # The marker travels toward the nearer vertical edge; on ties,
                # select the left edge. The divider itself is preserved.
                nc = c - 1 if c <= w - 1 - c else c + 1
                out[r][max(0, min(w - 1, nc))] = 4
    return out

